-- Glossario Web Design v2 — contenuti (generata, non modificare a mano).
--
-- Fonte: glossario-web-design-expansion.json (2026-09-29) normalizzato:
-- accenti al posto degli apostrofi, correzioni verificate su fonte primaria
-- il 2026-10-02 (rich result FAQ ritirati da Google il 7 maggio 2026, piano
-- Hobby di Vercel solo non commerciale, licenza GSAP gratuita anche per uso
-- commerciale, database supportati da EmDash), traduzione EN completa.
--
-- Ordine:
--   1. riallinea gli slug IT delle 28 voci storiche cercandole per TERMINE
--      (in produzione gli slug possono differire dal seed della 124)
--   2. merge SSL dentro HTTPS → https-ssl
--   3. correzioni IT (solo i campi elencati nel JSON)
--   4. voci storiche IT: upsert che, se la riga esiste, aggiorna SOLO i
--      metadati (categoria, livello, tipo, correlati): i testi modificati
--      da admin restano. Se manca, la crea con il testo corretto.
--   5. 78 voci nuove IT: upsert completo (is_published non toccato)
--   6. 106 voci EN: upsert completo
--   7. sort_order ricalcolato in ordine alfabetico dentro ogni lettera
--      (sovrascrive l'ordinamento manuale da admin)

-- 1) Slug allineati per termine ─────────────────────────────────────
UPDATE public.site_glossario g SET slug = 'accessibility'
WHERE g.locale = 'it' AND lower(g.term) = 'accessibility' AND g.slug <> 'accessibility'
  AND NOT EXISTS (SELECT 1 FROM public.site_glossario x WHERE x.locale = 'it' AND x.slug = 'accessibility');
