-- 2) SSL confluisce in HTTPS / SSL ──────────────────────────────────
DELETE FROM public.site_glossario
WHERE locale = 'it' AND lower(term) = 'ssl' AND slug <> 'https-ssl'
  AND EXISTS (SELECT 1 FROM public.site_glossario x WHERE x.locale = 'it' AND x.slug = 'https-ssl');

-- 3) Correzioni IT ─────────────────────────────────────────────────
UPDATE public.site_glossario SET why_you_care = E'Dal 28 giugno 2025 l''European Accessibility Act (in Italia D.Lgs. 82/2022) impone requisiti di accessibilità a prodotti e servizi specifici, tra cui e-commerce e servizi bancari al consumatore. Le microimprese che erogano servizi (meno di 10 addetti e fatturato o bilancio fino a 2 milioni di euro) sono esentate: verifica se rientri nell''ambito. Al di là dell''obbligo, un sito inaccessibile esclude clienti e ti espone a contestazioni.'
WHERE locale = 'it' AND slug = 'accessibility';
UPDATE public.site_glossario SET why_you_care = E'La velocità incide su esperienza, conversioni e ranking. Non è un numero unico ma l''insieme di LCP, CLS, INP e TTFB. Un sito lento perde visitatori prima ancora che leggano.', what_to_demand = E'Chiedi due cose distinte: un punteggio Lighthouse mobile di almeno 90 come obiettivo di laboratorio, e i Core Web Vitals sui dati reali degli utenti (CrUX) quando il sito ha abbastanza traffico per averli. Se il fornitore minimizza i numeri, sta proteggendo la sua incapacità tecnica.'
WHERE locale = 'it' AND slug = 'page-speed';
UPDATE public.site_glossario SET what_it_is = E'Approccio di design che parte dal mobile e poi adatta al desktop, perché la maggior parte della navigazione avviene da smartphone.', why_you_care = E'Google indicizza con il crawler mobile: se la versione mobile è povera o rotta, quella è la versione che conta per il ranking. Controlla nel tuo Analytics quanta parte dei tuoi visitatori arriva da mobile.'
WHERE locale = 'it' AND slug = 'mobile-first';
UPDATE public.site_glossario SET what_it_is = E'File di testo che dice ai bot dei motori di ricerca quali parti del sito non scansionare. È una richiesta di cortesia, non un blocco: chi vuole ignorarlo può farlo.', why_you_care = E'Un robots.txt sbagliato può far sparire l''intero sito da Google. E non protegge nulla: elencare un percorso sensibile lo rende pubblico e una pagina bloccata può comunque finire nei risultati se altri la linkano.', what_to_demand = E'Un robots.txt minimo che blocca solo ciò che non serve scansionare (ricerca interna, filtri infiniti) e indica la sitemap. Le aree private si proteggono con autenticazione, le pagine da non indicizzare con noindex.'
WHERE locale = 'it' AND slug = 'robots-txt';
UPDATE public.site_glossario SET why_you_care = E'Senza hreflang Google può mostrare la versione sbagliata al visitatore, oppure trattare le versioni come simili e sceglierne una sola, facendo perdere visibilità alle altre.'
WHERE locale = 'it' AND slug = 'hreflang';
UPDATE public.site_glossario SET why_you_care = E'Lo schema aiuta Google a capire cosa sono i contenuti e, per alcuni tipi, sblocca i rich result (recensioni, prodotti, breadcrumb). Non tutti i tipi generano un risultato speciale: le FAQ, per esempio, dal 2026 Google non le mostra più nei risultati.', what_to_demand = E'Schema coerente con il contenuto reale della pagina: Article, BreadcrumbList, Organization o LocalBusiness, Product dove serve, validati con il Rich Results Test. Diffida di chi promette stelline o FAQ in SERP: le FAQ non compaiono più, e gli altri rich result dipendono dal tipo di sito e dalle policy di Google.'
WHERE locale = 'it' AND slug = 'schema-markup';
UPDATE public.site_glossario SET what_to_demand = E'Chiedi l''LCP misurato, non un generico ''va veloce'': sia nel test di laboratorio con simulazione mobile sia, se disponibili, nei dati reali degli utenti (CrUX).'
WHERE locale = 'it' AND slug = 'lcp';
UPDATE public.site_glossario SET term = E'HTTPS / SSL', full_name = E'Certificato TLS (ex SSL) e protocollo sicuro', letter = 'H',
  what_it_is = E'HTTPS è la versione cifrata del protocollo web; SSL è il vecchio nome del certificato che lo abilita (oggi TLS). Il risultato visibile è il lucchetto nel browser: il traffico tra utente e sito è cifrato.',
  why_you_care = E'I browser segnalano ''Non sicuro'' i siti senza HTTPS e possono bloccare form e checkout. È un segnale di ranking leggero, ma soprattutto è fiducia: nessuno lascia i dati in un sito segnalato come non sicuro.',
  what_to_demand = E'Certificato incluso nell''hosting (Let''s Encrypt è gratuito e va bene) con rinnovo automatico e redirect da HTTP a HTTPS su tutte le pagine. Chi te lo fa pagare a parte sta gonfiando il conto.',
  aliases = ARRAY['ssl', 'tls', 'https', 'lucchetto', 'certificato ssl']::text[]
WHERE locale = 'it' AND slug = 'https-ssl';

-- 4) Voci storiche IT: metadati ─────────────────────────────────────
ON CONFLICT (slug, locale) DO UPDATE SET
  category = EXCLUDED.category,
  level = EXCLUDED.level,
  term_type = EXCLUDED.term_type,
  related = EXCLUDED.related;

-- 5) Voci nuove IT ──────────────────────────────────────────────────
ON CONFLICT (slug, locale) DO UPDATE SET
  term = EXCLUDED.term, full_name = EXCLUDED.full_name, letter = EXCLUDED.letter,
  category = EXCLUDED.category, level = EXCLUDED.level, term_type = EXCLUDED.term_type,
  aliases = EXCLUDED.aliases, related = EXCLUDED.related,
  what_it_is = EXCLUDED.what_it_is, why_you_care = EXCLUDED.why_you_care,
  what_to_demand = EXCLUDED.what_to_demand, what_for = EXCLUDED.what_for,
  when_yes = EXCLUDED.when_yes, when_no = EXCLUDED.when_no, what_to_ask = EXCLUDED.what_to_ask;

-- 6) Voci EN ────────────────────────────────────────────────────────
ON CONFLICT (slug, locale) DO UPDATE SET
  term = EXCLUDED.term, full_name = EXCLUDED.full_name, letter = EXCLUDED.letter,
  category = EXCLUDED.category, level = EXCLUDED.level, term_type = EXCLUDED.term_type,
  aliases = EXCLUDED.aliases, related = EXCLUDED.related,
  what_it_is = EXCLUDED.what_it_is, why_you_care = EXCLUDED.why_you_care,
  what_to_demand = EXCLUDED.what_to_demand, what_for = EXCLUDED.what_for,
  when_yes = EXCLUDED.when_yes, when_no = EXCLUDED.when_no, what_to_ask = EXCLUDED.what_to_ask;

-- 7) sort_order alfabetico per lettera ─────────────────────────────────
UPDATE public.site_glossario g
SET sort_order = o.rn
FROM (
  SELECT id, (row_number() OVER (PARTITION BY locale, letter ORDER BY lower(term), slug) - 1)::int AS rn
  FROM public.site_glossario
) o
WHERE g.id = o.id AND g.sort_order IS DISTINCT FROM o.rn;
